// article-bodies.jsx — long-form body content for each writing entry, keyed by slug.
// Block types the article template renders: p | h | code | ul | quote | img.
// Exposed on window.V3_ARTICLES so Article.html can look up by ?p=<slug>.
(function () {
  const ARTICLES = {
    "aws-waf-alb": {
      dek: "A hands-on walkthrough of deploying an intentionally exposed app with CloudFormation, attacking it, locking it down with AWS WAF managed rules and a custom rule, and tearing it all down cleanly.",
      body: [
        { t: "p", c: "An internet-facing Application Load Balancer gets probed fast. Scanners do not care how small your project is. They try /admin, they paste script tags into search boxes, and they poke at the instance metadata address looking for credentials." },
        { t: "p", c: "In this project I deployed an intentionally vulnerable web app behind an ALB, confirmed it accepted every bad request I sent, then put AWS WAF in front of it and ran the same tests again. Same attacks, different result. The whole environment comes from a CloudFormation template, so you can build it, break it, fix it, and delete it without leaving anything running on your bill." },
        { t: "quote", c: "Heads up: this app is vulnerable on purpose. Only deploy it in an AWS account you control, only test against your own resources, and tear it down when you finish." },
        { t: "h", c: "Architecture at a Glance" },
        { t: "img", src: "images/aws-waf-alb-01-architecture-diagram.png", alt: "Architecture diagram showing internet traffic reaching an EC2 instance through an Application Load Balancer", wide: true },
        { t: "p", c: "The flow: Internet → Application Load Balancer (HTTP on port 80) → target group → EC2 instance. After the fix, a web ACL sits on the ALB and inspects every request before it reaches the app." },
        { t: "p", c: "Services used:" },
        { t: "ul", c: ["AWS CloudFormation builds and deletes the environment.", "Application Load Balancer and EC2 host the sample app.", "AWS WAF filters requests with three AWS managed rule groups and one custom rule.", "AWS CloudShell sends the test traffic.", "CloudWatch metrics (through the WAF traffic overview) show what was allowed and blocked."] },
        { t: "h", c: "What You Need" },
        { t: "ul", c: ["An AWS account you control, with permission to create CloudFormation stacks, EC2 and load balancer resources, and WAF web ACLs. A sandbox account is ideal.", "The CloudFormation template (in Part 1).", "A browser and AWS CloudShell. The AWS CLI is optional.", "One region for everything. I used N. Virginia (us-east-1). A regional web ACL can only protect resources in its own region, so create the WAF in the same region as the ALB."] },
        { t: "h", c: "Part 1: Setup (Deploy the Environment)" },
        { t: "p", c: "CloudFormation builds the whole lab from one file, and just as useful, it removes it cleanly later. The template creates its own VPC with two public subnets, then deploys a small web app on a t3.micro EC2 instance behind an internet-facing ALB named waf-lab-alb, with a target group named waf-lab-tg. It also creates two security groups: one that lets the ALB accept HTTP from anywhere, and one that only lets the web server accept traffic from the ALB. Nothing in it creates IAM resources, so there is no capabilities checkbox to worry about." },
        { t: "p", c: "Here is the full template:" },
        { t: "code", c: "AWSTemplateFormatVersion: '2010-09-09'\nDescription: >-\n  WAF Lab baseline stack. Provisions a small PHP web app on EC2 fronted by an\n  internet-facing Application Load Balancer. No AWS WAF is attached, so\n  learners can find the exposed paths and then add WebACL controls.\n\nMetadata:\n  AWS::CloudFormation::Interface:\n    ParameterGroups:\n      - Label:\n          default: Compute\n        Parameters:\n          - AmiParam\n          - WebInstanceType\n      - Label:\n          default: Network\n        Parameters:\n          - VpcCidr\n          - ProjectPrefix\n\nParameters:\n  ProjectPrefix:\n    Type: String\n    Default: waf-lab\n    AllowedPattern: '^[a-zA-Z][a-zA-Z0-9-]{1,20}$'\n    Description: Prefix used in resource names and Name tags\n\n  VpcCidr:\n    Type: String\n    Default: 172.16.0.0/16\n    AllowedPattern: '^(\\d{1,3}\\.){3}\\d{1,3}/16$'\n    Description: /16 CIDR for the lab VPC (two /24 subnets are carved from it)\n\n  WebInstanceType:\n    Type: String\n    Default: t3.micro\n    Description: Instance size for the web tier\n\n  AmiParam:\n    Type: AWS::SSM::Parameter::Value<AWS::EC2::Image::Id>\n    Default: /aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-x86_64\n    Description: SSM parameter resolving to the latest Amazon Linux 2023 AMI\n\nResources:\n\n  # ---------------------------------------------------------------\n  # Network layer\n  # ---------------------------------------------------------------\n  LabVpc:\n    Type: AWS::EC2::VPC\n    Properties:\n      CidrBlock: !Ref VpcCidr\n      EnableDnsSupport: true\n      EnableDnsHostnames: true\n      Tags:\n        - Key: Name\n          Value: !Sub '${ProjectPrefix}-vpc'\n\n  LabIgw:\n    Type: AWS::EC2::InternetGateway\n    Properties:\n      Tags:\n        - Key: Name\n          Value: !Sub '${ProjectPrefix}-igw'\n\n  LabIgwAttachment:\n    Type: AWS::EC2::VPCGatewayAttachment\n    Properties:\n      VpcId: !Ref LabVpc\n      InternetGatewayId: !Ref LabIgw\n\n  SubnetAzA:\n    Type: AWS::EC2::Subnet\n    Properties:\n      VpcId: !Ref LabVpc\n      CidrBlock: !Select [0, !Cidr [!GetAtt LabVpc.CidrBlock, 2, 8]]\n      AvailabilityZone: !Select [0, !GetAZs '']\n      MapPublicIpOnLaunch: true\n      Tags:\n        - Key: Name\n          Value: !Sub '${ProjectPrefix}-subnet-a'\n\n  SubnetAzB:\n    Type: AWS::EC2::Subnet\n    Properties:\n      VpcId: !Ref LabVpc\n      CidrBlock: !Select [1, !Cidr [!GetAtt LabVpc.CidrBlock, 2, 8]]\n      AvailabilityZone: !Select [1, !GetAZs '']\n      MapPublicIpOnLaunch: true\n      Tags:\n        - Key: Name\n          Value: !Sub '${ProjectPrefix}-subnet-b'\n\n  InternetRouteTable:\n    Type: AWS::EC2::RouteTable\n    Properties:\n      VpcId: !Ref LabVpc\n      Tags:\n        - Key: Name\n          Value: !Sub '${ProjectPrefix}-rt'\n\n  DefaultInternetRoute:\n    Type: AWS::EC2::Route\n    DependsOn: LabIgwAttachment\n    Properties:\n      RouteTableId: !Ref InternetRouteTable\n      DestinationCidrBlock: 0.0.0.0/0\n      GatewayId: !Ref LabIgw\n\n  RtAssocA:\n    Type: AWS::EC2::SubnetRouteTableAssociation\n    Properties:\n      SubnetId: !Ref SubnetAzA\n      RouteTableId: !Ref InternetRouteTable\n\n  RtAssocB:\n    Type: AWS::EC2::SubnetRouteTableAssociation\n    Properties:\n      SubnetId: !Ref SubnetAzB\n      RouteTableId: !Ref InternetRouteTable\n\n  # ---------------------------------------------------------------\n  # Security groups (rules split out as standalone resources)\n  # ---------------------------------------------------------------\n  FrontendSg:\n    Type: AWS::EC2::SecurityGroup\n    Properties:\n      GroupDescription: Public HTTP access to the load balancer\n      VpcId: !Ref LabVpc\n      Tags:\n        - Key: Name\n          Value: !Sub '${ProjectPrefix}-frontend-sg'\n\n  FrontendHttpIn:\n    Type: AWS::EC2::SecurityGroupIngress\n    Properties:\n      GroupId: !Ref FrontendSg\n      IpProtocol: tcp\n      FromPort: 80\n      ToPort: 80\n      CidrIp: 0.0.0.0/0\n      Description: HTTP from the internet\n\n  BackendSg:\n    Type: AWS::EC2::SecurityGroup\n    Properties:\n      GroupDescription: HTTP from the load balancer only\n      VpcId: !Ref LabVpc\n      Tags:\n        - Key: Name\n          Value: !Sub '${ProjectPrefix}-backend-sg'\n\n  BackendHttpFromAlb:\n    Type: AWS::EC2::SecurityGroupIngress\n    Properties:\n      GroupId: !Ref BackendSg\n      IpProtocol: tcp\n      FromPort: 80\n      ToPort: 80\n      SourceSecurityGroupId: !Ref FrontendSg\n      Description: HTTP from the ALB security group\n\n  # ---------------------------------------------------------------\n  # Web server (launch template + instance)\n  # ---------------------------------------------------------------\n  WebLaunchTemplate:\n    Type: AWS::EC2::LaunchTemplate\n    Properties:\n      LaunchTemplateData:\n        ImageId: !Ref AmiParam\n        InstanceType: !Ref WebInstanceType\n        MetadataOptions:\n          HttpTokens: required\n          HttpEndpoint: enabled\n        UserData:\n          Fn::Base64: |\n            #!/bin/bash\n            set -e\n            dnf update -y\n            dnf install -y httpd php8.2 php8.2-fpm\n            WEBROOT=/var/www/html\n            mkdir -p \"$WEBROOT/admin\" \"$WEBROOT/api\"\n\n            # Home page\n            cat > \"$WEBROOT/index.html\" <<'HTML'\n            <!DOCTYPE html>\n            <html>\n            <head><title>WAF Lab - Sample Application</title></head>\n            <body>\n              <h1>Welcome to the WAF Lab Application</h1>\n              <p>Sample web app running behind an Application Load Balancer.</p>\n              <p>Status: <strong>Running</strong></p>\n              <ul>\n                <li><a href=\"/admin/\">Admin Panel</a></li>\n                <li><a href=\"/api/data\">API Endpoint</a></li>\n                <li><a href=\"/search.php?q=test\">Search</a></li>\n              </ul>\n            </body>\n            </html>\n            HTML\n\n            # Admin login page\n            cat > \"$WEBROOT/admin/index.html\" <<'HTML'\n            <!DOCTYPE html>\n            <html>\n            <head><title>Admin Panel</title></head>\n            <body>\n              <h1>Admin Panel</h1>\n              <p>Simulated admin area that should be protected.</p>\n              <form method=\"POST\" action=\"/admin/login\">\n                <label>Username: <input type=\"text\" name=\"username\"></label><br>\n                <label>Password: <input type=\"password\" name=\"password\"></label><br>\n                <button type=\"submit\">Login</button>\n              </form>\n            </body>\n            </html>\n            HTML\n\n            # API stub\n            echo '{\"status\":\"ok\",\"data\":[\"item1\",\"item2\",\"item3\"],\"server\":\"internal-web-01\"}' > \"$WEBROOT/api/data\"\n\n            # Search page (intentionally reflects input unescaped for the lab)\n            cat > \"$WEBROOT/search.php\" <<'PHP'\n            <!DOCTYPE html>\n            <html>\n            <head><title>Search Results</title></head>\n            <body>\n              <h1>Search Results</h1>\n              <p>You searched for: <?php echo $_GET['q']; ?></p>\n              <p>No results found.</p>\n            </body>\n            </html>\n            PHP\n\n            systemctl enable --now php-fpm\n            systemctl enable --now httpd\n            systemctl restart httpd\n\n  WebHost:\n    Type: AWS::EC2::Instance\n    Properties:\n      LaunchTemplate:\n        LaunchTemplateId: !Ref WebLaunchTemplate\n        Version: !GetAtt WebLaunchTemplate.LatestVersionNumber\n      SubnetId: !Ref SubnetAzA\n      SecurityGroupIds:\n        - !Ref BackendSg\n      Tags:\n        - Key: Name\n          Value: !Sub '${ProjectPrefix}-web'\n\n  # ---------------------------------------------------------------\n  # Load balancing\n  # ---------------------------------------------------------------\n  PublicAlb:\n    Type: AWS::ElasticLoadBalancingV2::LoadBalancer\n    Properties:\n      Name: !Sub '${ProjectPrefix}-alb'\n      Type: application\n      Scheme: internet-facing\n      Subnets:\n        - !Ref SubnetAzA\n        - !Ref SubnetAzB\n      SecurityGroups:\n        - !Ref FrontendSg\n      Tags:\n        - Key: Name\n          Value: !Sub '${ProjectPrefix}-alb'\n\n  WebTargets:\n    Type: AWS::ElasticLoadBalancingV2::TargetGroup\n    Properties:\n      Name: !Sub '${ProjectPrefix}-tg'\n      VpcId: !Ref LabVpc\n      Protocol: HTTP\n      Port: 80\n      TargetType: instance\n      Targets:\n        - Id: !Ref WebHost\n          Port: 80\n      HealthCheckPath: /\n      HealthCheckIntervalSeconds: 30\n      HealthyThresholdCount: 2\n      UnhealthyThresholdCount: 5\n      Tags:\n        - Key: Name\n          Value: !Sub '${ProjectPrefix}-tg'\n\n  PublicListener:\n    Type: AWS::ElasticLoadBalancingV2::Listener\n    Properties:\n      LoadBalancerArn: !Ref PublicAlb\n      Protocol: HTTP\n      Port: 80\n      DefaultActions:\n        - Type: forward\n          TargetGroupArn: !Ref WebTargets\n\nOutputs:\n  AppUrl:\n    Description: Public URL of the app (via ALB)\n    Value: !Sub 'http://${PublicAlb.DNSName}'\n\n  AlbDnsName:\n    Description: ALB DNS name\n    Value: !GetAtt PublicAlb.DNSName\n\n  AlbArn:\n    Description: ALB ARN (needed for the WAF WebACL association)\n    Value: !Ref PublicAlb\n\n  VpcId:\n    Description: VPC ID\n    Value: !Ref LabVpc\n\n  WebHostId:\n    Description: EC2 instance ID\n    Value: !Ref WebHost" },
        { t: "p", c: "Deploy with the console:" },
        { t: "p", c: "1. Save the template on your computer as template.yaml." },
        { t: "p", c: "2. Sign in to the AWS console and switch the region to N. Virginia (us-east-1)." },
        { t: "p", c: "3. In the search bar, enter CloudFormation and open it." },
        { t: "p", c: "4. Click Create stack, then With new resources (standard)." },
        { t: "p", c: "5. Under Specify template, choose Upload a template file, click Choose file, select template.yaml, and click Next." },
        { t: "p", c: "6. Enter a stack name. I used waf-lab. Leave the parameters at their defaults (the latest Amazon Linux 2023 AMI and a t3.micro instance), then click Next." },
        { t: "p", c: "7. On Configure stack options, leave the defaults and click Next. Optionally add a tag like project = waf-lab so leftovers are easy to spot during tear down." },
        { t: "p", c: "8. Review the settings and click Submit." },
        { t: "p", c: "9. Open the Events tab and wait for the stack status to reach CREATE_COMPLETE. This takes a few minutes. If you see ROLLBACK_COMPLETE instead, read the first failed event to find the cause, delete the stack, and try again." },
        { t: "p", c: "10. Open the Outputs tab. Copy the ALBDNSName value (or ApplicationURL, which is the same address with http:// in front). You will use it throughout the rest of this post." },
        { t: "p", c: "Or deploy with the CLI. You can do the same thing from CloudShell. Upload template.yaml using Actions, then Upload file, and run this. The deploy command waits until the stack finishes." },
        { t: "code", c: "aws cloudformation deploy \\\n  --template-file template.yaml \\\n  --stack-name waf-lab \\\n  --region us-east-1" },
        { t: "p", c: "Then grab the load balancer DNS name:" },
        { t: "code", c: "aws cloudformation describe-stacks \\\n  --stack-name waf-lab \\\n  --region us-east-1 \\\n  --query \"Stacks[0].Outputs[?OutputKey=='ALBDNSName'].OutputValue\" \\\n  --output text" },
        { t: "h", c: "Part 2: Establish the Baseline (Before WAF)" },
        { t: "p", c: "Before adding any protection, I wanted to see exactly what the app exposes." },
        { t: "p", c: "Inspect the load balancer:" },
        { t: "p", c: "1. Open the AWS console and make sure you are in N. Virginia (us-east-1)." },
        { t: "img", src: "images/aws-waf-alb-02-console-region.png", alt: "AWS console with the N. Virginia region selected", wide: true },
        { t: "p", c: "2. In the search bar, enter EC2 and select EC2." },
        { t: "img", src: "images/aws-waf-alb-03-search-ec2.png", alt: "Searching for EC2 in the console", wide: true },
        { t: "p", c: "3. In the left navigation, scroll down and select Load Balancers under Load Balancing." },
        { t: "img", src: "images/aws-waf-alb-04-load-balancers-nav.png", alt: "Load Balancers in the EC2 left navigation", wide: true },
        { t: "p", c: "4. Select waf-lab-alb. On the Details tab you can see the VPC, Availability Zones, DNS name, and scheme." },
        { t: "img", src: "images/aws-waf-alb-05-alb-details.png", alt: "Load balancer details tab", wide: true },
        { t: "p", c: "5. Open the Resource map tab. A single HTTP listener on port 80 forwards to the target group waf-lab-tg, which has one EC2 instance behind it." },
        { t: "img", src: "images/aws-waf-alb-06-alb-resource-map.png", alt: "Resource map showing one HTTP listener, the target group, and one instance", wide: true },
        { t: "quote", c: "Why this matters: there is no HTTPS listener, so everything crosses the wire unencrypted. WAF will not fix that. In production you would add an HTTPS listener with an ACM certificate and redirect port 80 to 443." },
        { t: "p", c: "Inspect the security group:" },
        { t: "p", c: "1. Click the Security tab, then click the Security Group ID. It opens in a new tab." },
        { t: "img", src: "images/aws-waf-alb-07-alb-security-tab.png", alt: "Security tab on the load balancer", wide: true },
        { t: "p", c: "2. On the Inbound rules tab you will see one rule: HTTP, port 80, source 0.0.0.0/0." },
        { t: "img", src: "images/aws-waf-alb-08-sg-inbound-rules.png", alt: "Inbound rule allowing HTTP from anywhere", wide: true },
        { t: "p", c: "That is normal for a public ALB, but it also means nothing at the network layer is filtering who can talk to the app." },
        { t: "p", c: "Use the application:" },
        { t: "p", c: "1. Go back to the load balancer Details tab and copy the DNS name." },
        { t: "p", c: "2. Open a new browser tab and enter the DNS name with http:// in front of it. You will see the homepage titled Welcome to the WAF Lab Application, with links to Admin Panel, API Endpoint, and Search." },
        { t: "img", src: "images/aws-waf-alb-09-app-homepage.png", alt: "Application homepage", wide: true },
        { t: "p", c: "3. Click Admin Panel (or add /admin to the URL). You get a login form that anyone on the internet can reach." },
        { t: "img", src: "images/aws-waf-alb-10-admin-panel.png", alt: "Admin panel login form", wide: true },
        { t: "p", c: "4. Go back and click API Endpoint. The JSON response includes a server field that leaks the hostname." },
        { t: "img", src: "images/aws-waf-alb-11-api-endpoint.png", alt: "API endpoint JSON response leaking the server hostname", wide: true },
        { t: "p", c: "5. Go back and click Search. The page echoes your query back with a \"No results found\" message." },
        { t: "img", src: "images/aws-waf-alb-12-search-page.png", alt: "Search page echoing the query", wide: true },
        { t: "p", c: "Attack it on purpose. Now I wanted to see how the app handles common attack patterns with no protection in place. Only run these against your own lab resources." },
        { t: "p", c: "1. In the browser, change q=test in the URL to the payload below and press Enter." },
        { t: "code", c: "http://<ALB_DNS>/search.php?q=<script>alert('xss')</script>" },
        { t: "img", src: "images/aws-waf-alb-13-xss-url.png", alt: "Browser URL with the XSS payload in the query string", wide: true },
        { t: "p", c: "An alert box containing xss pops up. The app renders user input straight into the page without sanitizing it, which is reflected cross-site scripting." },
        { t: "p", c: "2. If you are on a corporate or managed network, your endpoint security may block this before it reaches the app and show a warning page instead. That is your security tooling doing its job, not a problem with the lab." },
        { t: "img", src: "images/aws-waf-alb-14-xss-block-page.png", alt: "Block page from corporate security software", wide: true },
        { t: "p", c: "3. Open AWS CloudShell from the lower-left corner of the console and resize the window if you need to." },
        { t: "img", src: "images/aws-waf-alb-15-cloudshell.png", alt: "AWS CloudShell in the console", wide: true },
        { t: "p", c: "4. Send a request with a scanner-style user agent. Replace <ALB_DNS> with your DNS name." },
        { t: "code", c: "curl -o /dev/null -s -w \"HTTP Status: %{http_code}\\n\" -H \"User-Agent: sqlmap/1.5\" \"http://<ALB_DNS>/\"" },
        { t: "p", c: "Expected result: HTTP Status: 200. The app happily served a request that identified itself as sqlmap." },
        { t: "p", c: "5. Send a request that tries to reach the instance metadata service through user input." },
        { t: "code", c: "curl -o /dev/null -s -w \"HTTP Status: %{http_code}\\n\" \"http://<ALB_DNS>/search.php?q=http://169.254.169.254/latest/meta-data/iam/security-credentials/\"" },
        { t: "p", c: "Expected result: HTTP Status: 200." },
        { t: "img", src: "images/aws-waf-alb-16-baseline-200-results.png", alt: "CloudShell output showing HTTP Status 200 for both requests", wide: true },
        { t: "p", c: "The address 169.254.169.254 is the EC2 instance metadata service, and SSRF attacks aim at it to steal temporary IAM credentials. This app only echoes the input back and never fetches the URL, but a request shaped like this is exactly what you want blocked at the edge." },
        { t: "p", c: "Baseline result: every request came back 200. No filtering, no rate limiting, no access control. Time to fix that." },
        { t: "h", c: "Part 3: Create the Web ACL" },
        { t: "p", c: "A web ACL is the container for your WAF rules. I used three AWS managed rule groups plus one custom rule." },
        { t: "quote", c: "Console note: AWS is rolling out a newer WAF console experience, so your screens may look different. If you land on a page with a Create protection pack (web ACL) button, look for Switch to the old WAF console in the left navigation and use that. The steps below follow the classic flow." },
        { t: "p", c: "Here is what the three managed rule groups cover:" },
        { t: "ul", c: ["Admin protection: blocks requests to commonly exposed admin pages.", "Core rule set: broad baseline coverage of OWASP-style threats, including XSS and an EC2 metadata SSRF check on query strings.", "Known bad inputs: blocks request patterns tied to known exploits and vulnerability discovery."] },
        { t: "p", c: "1. In the console search bar, enter waf and select WAF & Shield. If CloudShell is still open, close it." },
        { t: "img", src: "images/aws-waf-alb-17-search-waf.png", alt: "Searching for WAF in the console", wide: true },
        { t: "p", c: "2. If needed, click Switch to the old WAF console in the left navigation." },
        { t: "img", src: "images/aws-waf-alb-18-switch-old-console.png", alt: "Switch to the old WAF console link", wide: true },
        { t: "p", c: "3. Click Create web ACL." },
        { t: "p", c: "4. On Describe web ACL and associate it to AWS resources, set the following:" },
        { t: "ul", c: ["Resource type: Regional resources", "Region: US East (N. Virginia)", "Name: waf-lab-waf", "CloudWatch metric name: auto-fills with waf-lab-waf"] },
        { t: "p", c: "5. Under Associated AWS resources, click Add AWS resources." },
        { t: "img", src: "images/aws-waf-alb-19-add-aws-resources.png", alt: "Add AWS resources button", wide: true },
        { t: "p", c: "6. In the pop-up, select Application Load Balancer, check waf-lab-alb, and click Add. Leave everything else alone and click Next." },
        { t: "img", src: "images/aws-waf-alb-20-select-alb.png", alt: "Selecting the Application Load Balancer to associate", wide: true },
        { t: "p", c: "7. On Add rules and rule groups, open the Add rules drop-down and choose Add managed rule groups." },
        { t: "img", src: "images/aws-waf-alb-21-add-managed-rule-groups.png", alt: "Add managed rule groups option", wide: true },
        { t: "p", c: "8. Expand AWS managed rule groups. Under Free rule groups, toggle Add to web ACL for Admin protection, Core rule set, and Known bad inputs." },
        { t: "img", src: "images/aws-waf-alb-22-free-rule-groups.png", alt: "Toggling the three free managed rule groups", wide: true },
        { t: "p", c: "9. Click Add rules at the bottom of the page." },
        { t: "p", c: "10. Back on Add rules and rule groups, click Add rules again and choose Add my own rules and rule groups." },
        { t: "img", src: "images/aws-waf-alb-23-add-own-rules.png", alt: "Add my own rules and rule groups option", wide: true },
        { t: "p", c: "11. Select Rule builder and set these values, then click Add rule:" },
        { t: "ul", c: ["Name: BlockAdminAccess", "Type: Regular rule", "If a request: matches the statement", "Inspect: URI path", "Match type: Starts with string", "String to match: /admin", "Text transformation: Lowercase", "Action: Block"] },
        { t: "img", src: "images/aws-waf-alb-24-rule-builder.png", alt: "Rule builder configured for BlockAdminAccess", wide: true },
        { t: "p", c: "12. You should now see four rules: the three managed rule groups and BlockAdminAccess. Click Next." },
        { t: "img", src: "images/aws-waf-alb-25-four-rules.png", alt: "Four rules listed on the web ACL", wide: true },
        { t: "p", c: "13. On Set rule priority, leave the default order and click Next. Rules run top to bottom, and a request that gets blocked stops there, so a request caught by a managed group never reaches your custom rule." },
        { t: "img", src: "images/aws-waf-alb-26-rule-priority.png", alt: "Rule priority page", wide: true },
        { t: "p", c: "14. On Configure metrics, leave the defaults and click Next." },
        { t: "img", src: "images/aws-waf-alb-27-configure-metrics.png", alt: "Configure metrics page", wide: true },
        { t: "p", c: "15. On Review and create web ACL, check your settings and click Create web ACL. Give it a few minutes to finish." },
        { t: "quote", c: "Production note: a blanket block on /admin is fine for a lab, but it is blunt. In production I would allow only trusted IP addresses, and add URL decoding and path normalization as text transformations so encoded variants do not slip past. I would also roll out any new rule in Count mode first, review what it would have blocked, and only then switch it to Block." },
        { t: "h", c: "Part 4: Validate the Protection" },
        { t: "p", c: "In every command below, replace <ALB_DNS> with your load balancer's DNS name." },
        { t: "p", c: "Re-run the attacks. Open CloudShell and run these. Each one should now return HTTP Status: 403." },
        { t: "p", c: "1. The XSS payload:" },
        { t: "code", c: "curl -o /dev/null -s -w \"HTTP Status: %{http_code}\\n\" \"http://<ALB_DNS>/search.php?q=<script>alert('xss')</script>\"" },
        { t: "p", c: "This should match the XSS check on query arguments in the core rule set (AWSManagedRulesCommonRuleSet)." },
        { t: "p", c: "2. The admin path:" },
        { t: "code", c: "curl -o /dev/null -s -w \"HTTP Status: %{http_code}\\n\" \"http://<ALB_DNS>/admin\"" },
        { t: "p", c: "This is the path BlockAdminAccess targets. The Admin protection group sits above it in the priority order, so it may be the one that fires first. Check the sampled requests on the web ACL to see which rule actually matched." },
        { t: "p", c: "3. The metadata service probe:" },
        { t: "code", c: "curl -o /dev/null -s -w \"HTTP Status: %{http_code}\\n\" \"http://<ALB_DNS>/search.php?q=http://169.254.169.254/latest/meta-data/iam/security-credentials/\"" },
        { t: "p", c: "The core rule set includes an EC2 metadata SSRF check for query arguments, which is the rule I would expect to catch this." },
        { t: "p", c: "Make sure real traffic still works. Protection that breaks the app is not protection. These should all return HTTP Status: 200." },
        { t: "p", c: "1. The homepage:" },
        { t: "code", c: "curl -o /dev/null -s -w \"HTTP Status: %{http_code}\\n\" \"http://<ALB_DNS>/\"" },
        { t: "p", c: "2. A normal API request:" },
        { t: "code", c: "curl -o /dev/null -s -w \"HTTP Status: %{http_code}\\n\" \"http://<ALB_DNS>/api/data\"" },
        { t: "p", c: "3. A normal search:" },
        { t: "code", c: "curl -o /dev/null -s -w \"HTTP Status: %{http_code}\\n\" \"http://<ALB_DNS>/search.php?q=cloud+computing\"" },
        { t: "p", c: "4. Optionally, open http://<ALB_DNS>/ in a browser. The app should load normally." },
        { t: "quote", c: "Try it yourself: I did not re-run the sqlmap user agent request from the baseline test after adding the WAF. Run it again and see what your web ACL does with it. Compare the status code with what you got before, and check the sampled requests either way." },
        { t: "p", c: "Review the WAF metrics:" },
        { t: "p", c: "1. In the console, go to WAF & Shield and click Web ACLs in the left navigation." },
        { t: "p", c: "2. Select waf-lab-waf." },
        { t: "img", src: "images/aws-waf-alb-28-select-web-acl.png", alt: "Selecting the web ACL from the list", wide: true },
        { t: "p", c: "3. On the Traffic overview tab, look at Allowed Requests, Blocked Requests, and Traffic characteristics. The blocked requests line up with the attacks you sent and the allowed requests line up with the legitimate ones." },
        { t: "img", src: "images/aws-waf-alb-29-traffic-overview.png", alt: "WAF traffic overview showing allowed and blocked requests", wide: true },
        { t: "p", c: "That is the full proof: the same attacks that returned 200 before now return 403, and normal traffic still gets through." },
        { t: "h", c: "Part 5: Tear Down" },
        { t: "p", c: "Do this the same day. You created the web ACL by hand, so deleting the CloudFormation stack will not remove it, and it keeps billing by the hour whether or not it sees any traffic." },
        { t: "p", c: "Order matters. AWS will not let you delete a web ACL that is still attached to a resource, so detach it first, then delete it, then delete the stack." },
        { t: "p", c: "Tear down with the console:" },
        { t: "p", c: "1. Disassociate the web ACL. Go to WAF & Shield, then Web ACLs (make sure the region is us-east-1). Select waf-lab-waf, open the Associated AWS resources tab, select waf-lab-alb, and click Disassociate. Confirm." },
        { t: "p", c: "2. Delete the web ACL. Go back to Web ACLs, select waf-lab-waf, click Delete, and confirm." },
        { t: "p", c: "3. Delete the stack. Go to CloudFormation, select waf-lab, click Delete, and confirm. Watch the Events tab until the stack is gone. If it shows DELETE_FAILED, read the failed event, fix what it points to, and delete again." },
        { t: "p", c: "4. Verify nothing is left. Check that EC2 > Load Balancers and Target Groups are empty, the instance shows as terminated, and the waf-lab-vpc VPC (with its subnets and security groups) is gone. Then confirm WAF & Shield > Web ACLs has nothing in us-east-1." },
        { t: "p", c: "5. Check your bill. Look at Billing or Cost Explorer a day later. Setting up an AWS Budgets alert is a cheap way to catch anything you forgot." },
        { t: "p", c: "Or tear down with the CLI from CloudShell:" },
        { t: "code", c: "REGION=us-east-1\n\n# 1. Find the ALB and the web ACL\nALB_ARN=$(aws elbv2 describe-load-balancers --names waf-lab-alb --region $REGION --query 'LoadBalancers[0].LoadBalancerArn' --output text)\nWAF_ID=$(aws wafv2 list-web-acls --scope REGIONAL --region $REGION --query \"WebACLs[?Name=='waf-lab-waf'].Id | [0]\" --output text)\n\n# 2. Detach the web ACL from the ALB\naws wafv2 disassociate-web-acl --resource-arn \"$ALB_ARN\" --region $REGION\n\n# 3. Delete the web ACL (this call needs a lock token)\nLOCK_TOKEN=$(aws wafv2 get-web-acl --name waf-lab-waf --scope REGIONAL --id \"$WAF_ID\" --region $REGION --query 'LockToken' --output text)\naws wafv2 delete-web-acl --name waf-lab-waf --scope REGIONAL --id \"$WAF_ID\" --lock-token \"$LOCK_TOKEN\" --region $REGION\n\n# 4. Delete the stack and wait for it to finish\naws cloudformation delete-stack --stack-name waf-lab --region $REGION\naws cloudformation wait stack-delete-complete --stack-name waf-lab --region $REGION\n\n# 5. Confirm nothing is left\naws wafv2 list-web-acls --scope REGIONAL --region $REGION\naws elbv2 describe-load-balancers --region $REGION --query 'LoadBalancers[].LoadBalancerName'" },
        { t: "h", c: "What I Would Do Differently in Production" },
        { t: "ul", c: ["Treat WAF as a compensating control, not the fix. The XSS is still in the app. Encode output properly, and stop leaking the server hostname from the API.", "Encrypt the traffic. Add an HTTPS listener with an ACM certificate and redirect HTTP to HTTPS.", "Lock down admin paths properly. Allow trusted IPs only, or put the admin panel behind SSO or a VPN instead of relying on a path match.", "Roll out rules in Count mode first. Review what would have been blocked before you start blocking real users.", "Turn on WAF logging. Blocked requests are only useful if you can investigate them later.", "Add a rate-based rule to slow down brute force attempts against login pages.", "Put the web ACL in the CloudFormation template too. Then the whole environment comes down with one stack delete, and there is no orphaned WAF to forget."] },
        { t: "p", c: "That is the full loop: deploy, attack, protect, verify, delete. Same tests, different results, and a clean account at the end." },
      ],
    },

    "flaws2-level1": {
      dek: "Playing the attacker in flaws2.cloud. We bypass a client-side check, extract temporary AWS credentials from a verbose error, and use them to read a private S3 bucket.",
      body: [
        { t: "img", src: "images/flaws2-level1-inline-1.png", alt: "flAWS 2 challenge landing page" },
        { t: "p", c: "flaws2.cloud is a free, intentionally vulnerable AWS training environment built by Scott Piper. It has two tracks, attacker and defender, and it teaches cloud security by letting you actually exploit the misconfigurations instead of just reading about them. In this post I play the attacker side of Level 1, where the goal is to get past a login screen and read a protected S3 bucket." },
        { t: "p", c: "If you want to follow along, start at the challenge and pick Attacker. A quick heads-up on credentials: everything you extract here is a short-lived STS session token that expires fast and belongs to a throwaway training account, so I have redacted the values below. Never paste real leaked keys into a public writeup." },

        { t: "h", c: "The Setup" },
        { t: "p", c: "Level 1 presents a screen asking for a code that the instructions say is \"100 digits long.\" Two ways to win: find the code, or bypass the check entirely. We go for the bypass." },
        { t: "img", src: "images/flaws2-level1-inline-2.png", alt: "flaws2.cloud Level 1 PIN code challenge" },

        { t: "h", c: "Step 1: Watch the Request" },
        { t: "p", c: "First, submit a few random digits just to see the behavior. Then open your browser's developer tools (F12) and switch to the Network tab. Submit again and inspect what actually goes over the wire." },
        { t: "img", src: "images/flaws2-level1-inline-3.png", alt: "flaws2.cloud Level 1 with random digits submitted as the code" },
        { t: "img", src: "images/flaws2-level1-inline-4.png", alt: "Browser Network tab showing the request after submitting an incorrect code" },

        { t: "h", c: "Step 2: Break the Assumption" },
        { t: "p", c: "The instructions say the code is 100 digits. So what happens if we submit a letter instead? Try it, and a JavaScript popup blocks the submission." },
        { t: "img", src: "images/flaws2-level1-inline-5.png", alt: "JavaScript alert reading Code must be a number after submitting a letter" },
        { t: "p", c: "That popup is the tell. It is a client-side validation check, which means it only runs in your browser and can be trivially bypassed. The server never sees it." },

        { t: "h", c: "Step 3: Bypass the Client-Side Check" },
        { t: "p", c: "In the Network tab, right-click the submitted request and choose Edit and Resend (Firefox makes this easy). Change the code parameter to a single character and send it." },
        { t: "img", src: "images/flaws2-level1-inline-6.png", alt: "Edit and Resend panel showing the code parameter changed to a single character, resulting in a 500 response" },
        { t: "p", c: "This time the server responds with a 500 Internal Server Error. A 500 means the backend choked on our unexpected input, and a crashing backend often leaks more than it should." },

        { t: "h", c: "Step 4: Read the Verbose Error" },
        { t: "p", c: "Following the request's initiator into the response, the error dump contains exactly what an attacker dreams of: a full set of temporary AWS credentials that were injected into the Lambda's environment." },
        { t: "img", src: "images/flaws2-level1-inline-7.png", alt: "Raw 500 response body showing leaked AWS Lambda environment variables including access key, secret key, and session token" },
        { t: "code", c: "AWS_ACCESS_KEY_ID: ASIA...REDACTED\nAWS_SECRET_ACCESS_KEY: ...REDACTED\nAWS_SESSION_TOKEN: ...REDACTED\nAWS_REGION: us-east-1" },
        { t: "p", c: "The lesson here: verbose error messages that expose environment variables are a serious information-disclosure flaw. The backend should return a generic error and log the details privately." },

        { t: "h", c: "Step 5: Use the Stolen Credentials" },
        { t: "p", c: "Install the AWS CLI, then load the leaked credentials into a named profile so we do not pollute our real config:" },
        { t: "code", c: "# Configure a throwaway profile with the leaked temporary credentials.\n# You will also need to add aws_session_token, since these are STS creds.\naws configure --profile flaws2-level1" },
        { t: "p", c: "Next, fingerprint the target to confirm what we are dealing with:" },
        { t: "code", c: "# -I fetches headers only. The Server header reveals this is AmazonS3.\ncurl -I http://level1.flaws2.cloud" },
        { t: "img", src: "images/flaws2-level1-inline-8.png", alt: "Terminal output of curl -I against level1.flaws2.cloud showing the Server: AmazonS3 header" },
        { t: "p", c: "The response confirms the site is hosted on S3. Now we test whether our stolen identity can list the bucket:" },
        { t: "code", c: "# List the bucket contents using the compromised credentials.\naws s3 ls s3://level1.flaws2.cloud --profile flaws2-level1" },
        { t: "img", src: "images/flaws2-level1-inline-9.png", alt: "Terminal output listing the level1.flaws2.cloud bucket contents, including a secret HTML file" },
        { t: "p", c: "Access granted. And right there in the listing is an object named secret." },

        { t: "h", c: "Step 6: Grab the Loot" },
        { t: "code", c: "# Copy the secret object to stdout (the trailing - streams it to the terminal).\naws s3 cp s3://level1.flaws2.cloud/secret-REDACTED.html - --profile flaws2-level1" },
        { t: "img", src: "images/flaws2-level1-inline-10.png", alt: "Level 1 secret page revealing the URL for Level 2" },
        { t: "p", c: "(You can also just open the object URL in a browser.) The file hands us the URL for Level 2." },

        { t: "h", c: "What Just Happened" },
        { t: "p", c: "In six steps we chained three separate weaknesses:" },
        { t: "ul", c: [
          "Client-side-only validation. The 100-digit check ran in the browser, so it was bypassable with Edit and Resend",
          "Verbose error handling. A 500 error leaked live AWS credentials from the Lambda environment",
          "Over-permissioned credentials. Those credentials could list and read a private S3 bucket",
        ] },
        { t: "p", c: "Any one of these alone is a finding. Chained together, they turn a login screen into full bucket access. That is the real lesson of cloud security: attackers do not need a single catastrophic bug, just a few small ones lined up." },

        { t: "h", c: "Defender Takeaways" },
        { t: "ul", c: [
          "Validate on the server, always. Client-side checks are UX, not security",
          "Return generic errors to users; log the details somewhere private",
          "Scope credentials tightly. The Lambda role should not have had read access to that bucket if it did not need it",
          "Rotate and time-box credentials, which STS tokens do by default, limiting the blast radius",
        ] },
        { t: "p", c: "In the next post I will work through Level 2, where things get more interesting. Same target, deeper access." },
      ],
    },
    "identity-management-cognito": {
      dek: "A hands-on walkthrough of building a university portal login system with Cognito: MFA enforcement, custom password policies, role-based groups, and OIDC integration with a React frontend.",
      body: [
        { t: "p", c: "Identity is the new perimeter. Before an attacker ever touches your data, they touch your login page, which makes authentication one of the highest-value places to invest security effort. In this project I built a complete identity system for a simulated university portal using Amazon Cognito: students and professors sign in with MFA, strong password policies are enforced, and role-based groups set the stage for least-privilege access to backend data." },
        { t: "p", c: "Here is the full walkthrough." },

        { t: "h", c: "Architecture at a Glance" },
        { t: "p", c: "The flow: User → React frontend → Cognito Hosted UI (OIDC) → JWT tokens → group-based authorization." },
        { t: "p", c: "Services used:" },
        { t: "ul", c: [
          "Amazon Cognito User Pool handles authentication, MFA, and group management",
          "Cognito App Client + Hosted Domain provide standards-based login pages",
          "AWS IAM maps groups to permissions (read-only for students, read/write for professors)",
          "React + react-oidc-context for the frontend integration",
        ] },
        { t: "p", c: "Time: 3 to 4 hours. Cost: free under the AWS Free Tier." },
        { t: "p", c: "Key terms upfront:" },
        { t: "ul", c: [
          "User Pool: Cognito's user directory, where accounts, passwords, and MFA live",
          "OIDC (OpenID Connect): the standard protocol that lets your app delegate login to Cognito",
          "JWT: the signed token your app receives after login, proving who the user is and what groups they belong to",
        ] },

        { t: "h", c: "Step 1: Create the User Pool" },
        { t: "ul", c: [
          "In the Cognito console, click User pools → Create user pool",
          "Application type: Traditional web application. Name it something like UniversityPortalUsers",
          "Sign-in identifier: Email only. Required attributes: Email",
          "Optionally add a return URL (http://localhost:3000 for local testing)",
          "Click Create user directory",
        ] },

        { t: "h", c: "Step 2: Harden the Security Settings" },
        { t: "p", c: "This is where the project earns its \"security\" label." },
        { t: "p", c: "Enforce MFA:" },
        { t: "ul", c: [
          "Go to Authentication → Sign-in → Multi-factor authentication → Edit",
          "Set enforcement to Required",
          "Choose TOTP (authenticator app) as the second factor. TOTP is preferable to SMS, which is vulnerable to SIM-swapping",
        ] },
        { t: "p", c: "Set a custom password policy:" },
        { t: "ul", c: [
          "Go to Authentication → Authentication methods → Password policy",
          "Mode: Custom, minimum 8 characters, require uppercase, lowercase, number, and special character",
          "Temporary password validity: 7 days",
        ] },
        { t: "p", c: "Enable account recovery:" },
        { t: "ul", c: [
          "Under User account recovery, enable self-service recovery",
          "Set Email as the preferred delivery method",
        ] },

        { t: "h", c: "Step 3: Create Role-Based Groups" },
        { t: "p", c: "Groups are how Cognito supports RBAC. Group membership shows up as a claim inside the JWT, so your backend can make authorization decisions without extra lookups." },
        { t: "ul", c: [
          "Go to User management → Groups → Create group",
          "Create Students (later mapped to read-only data access)",
          "Create Professors (later mapped to read/write access)",
        ] },
        { t: "p", c: "IAM roles get attached to these groups when you wire up backend APIs. For now the groups just tag identities with their role." },

        { t: "h", c: "Step 4: Configure the App Client and Hosted Domain" },
        { t: "p", c: "The App Client represents your application; the hosted domain gives you a ready-made, Cognito-managed login page." },
        { t: "ul", c: [
          "In App clients, verify the client that was auto-created with your pool",
          "Open the Login pages tab → Managed login pages configuration",
          "Set both the Callback URL and Sign-out URL to http://localhost:3000 for local testing, then save",
          "Under Branding → Domain, confirm a Cognito domain exists (e.g., yourprefix.auth.us-east-1.amazoncognito.com). If not, create one with a unique prefix",
        ] },

        { t: "h", c: "Step 5: Create Test Users and Assign Groups" },
        { t: "ul", c: [
          "Go to User management → Users → Create user",
          "Create student01@example.com with a temporary password, marking the email verified for quick testing",
          "Open the user, scroll to Group memberships → Add to group, and add them to Students",
          "Repeat with professor01@example.com in the Professors group",
        ] },

        { t: "h", c: "Step 6: Integrate the React Frontend via OIDC" },
        { t: "p", c: "Scaffold the app:" },
        { t: "code", c: "npx create-react-app university-portal\ncd university-portal\nnpm start" },
        { t: "p", c: "In the Cognito console, open App client → Quick setup guide. AWS generates working index.js and App.js code using react-oidc-context with your exact authority, client_id, and redirect URIs already filled in. Copy that code into your project and restart the dev server." },
        { t: "p", c: "Test the full flow:" },
        { t: "ul", c: [
          "Open http://localhost:3000 and click Sign In",
          "You are redirected to the Cognito-hosted login page",
          "Log in as the test student. Cognito forces a password reset and MFA enrollment (scan the QR code with an authenticator app)",
          "After MFA setup, Cognito redirects back with valid JWT tokens",
          "Sign out and verify the session ends",
        ] },
        { t: "p", c: "That forced password-reset-plus-MFA-enrollment flow on first login is exactly what you want: no user enters the system without a strong credential and a second factor." },

        { t: "h", c: "Production Notes" },
        { t: "p", c: "The lab keeps things simple, but a few things change before this pattern ships:" },
        { t: "ul", c: [
          "Never display tokens in the UI. Store them in httpOnly cookies rather than localStorage",
          "HTTPS everywhere. Localhost is fine for testing only",
          "Limit OAuth scopes to what the app needs (openid, email)",
          "Link identities to records with custom attributes like StudentID instead of storing sensitive data (grades, assignments) in Cognito itself. Cognito authenticates; your database authorizes",
        ] },

        { t: "h", c: "Cleanup" },
        { t: "ul", c: [
          "Delete the Cognito User Pool (this removes users, groups, and the app client)",
          "Remove any extra test app clients",
          "Confirm no hosted domains remain",
        ] },

        { t: "h", c: "Key Takeaways" },
        { t: "ul", c: [
          "MFA required, not optional. Enforcing TOTP at the pool level means no account can skip it",
          "RBAC through groups. Group claims in the JWT give your backend clean, token-based authorization",
          "Standards over custom code. OIDC with the hosted UI means no hand-rolled login forms and no password handling in your app",
          "Separation of concerns. Cognito owns authentication; your data layer owns authorization",
        ] },
        { t: "p", c: "This pattern maps directly to real identity work: it is the same OIDC flow enterprises run through Okta or Entra ID, just with AWS-native tooling. If you understand this project, you understand the core of modern SSO." },
      ],
    },
    "secure-serverless-website": {
      dek: "A step-by-step walkthrough of hosting a static site the secure way: private S3 bucket, CloudFront with Origin Access Control, AWS WAF managed rules, least-privilege IAM, and monitoring with CloudWatch and CloudTrail.",
      body: [
        { t: "p", c: "Most \"host a static site on S3\" tutorials tell you to make the bucket public. That works, but it is not how you would do it in production, and it is definitely not how a security engineer should do it. In this project I built a secure, serverless website architecture where the S3 bucket stays completely private, CloudFront is the only allowed reader, AWS WAF filters malicious traffic at the edge, and everything is auditable." },
        { t: "p", c: "Here is the full walkthrough." },

        { t: "h", c: "Architecture at a Glance" },
        { t: "p", c: "The flow: User → CloudFront (HTTPS enforced) → WAF inspection → Origin Access Control → private S3 bucket." },
        { t: "p", c: "Services used:" },
        { t: "ul", c: [
          "Amazon S3 stores the static site files (HTML, CSS, JS)",
          "Amazon CloudFront delivers content globally over HTTPS",
          "AWS WAF blocks SQL injection, XSS, and known bad traffic",
          "AWS IAM enforces least-privilege access for administration",
          "CloudWatch and CloudTrail provide monitoring and an audit trail",
        ] },
        { t: "p", c: "Time: 1 to 2 hours. Cost: roughly $0.50 to $1.50 if you clean up afterward." },

        { t: "h", c: "Step 1: Create a Private S3 Bucket" },
        { t: "p", c: "The key decision here: the bucket never becomes public." },
        { t: "ul", c: [
          "In the S3 console, click Create bucket",
          "Give it a globally unique name (e.g., my-site-website) and pick a region close to your users",
          "Leave Block all public access enabled (the default)",
          "Leave versioning, tags, and encryption at defaults and create the bucket",
          "Open the bucket and Upload your site files (index.html, web.css, web.js)",
        ] },
        { t: "p", c: "Why this matters: with public access blocked, nobody can hit your objects directly over the internet. CloudFront, via Origin Access Control, will be the only path in." },

        { t: "h", c: "Step 2: Set Up CloudFront with Origin Access Control" },
        { t: "p", c: "CloudFront caches your content at edge locations worldwide and terminates TLS for you." },
        { t: "ul", c: [
          "In CloudFront, go to Distributions → Create Distribution",
          "Origin type: Amazon S3. Origin domain: select your bucket's REST endpoint (bucket.s3.region.amazonaws.com), not the S3 website endpoint. The website endpoint cannot enforce HTTPS to the origin",
          "Keep private S3 bucket access via OAC enabled so only CloudFront can fetch objects",
          "Viewer protocol policy: Redirect HTTP to HTTPS",
          "Allowed HTTP methods: GET, HEAD only (a static site needs nothing else)",
          "Cache policy: CachingOptimized",
          "Skip WAF for now (we attach it manually in Step 3) and create the distribution",
        ] },
        { t: "p", c: "Then wire up the bucket policy:" },
        { t: "ul", c: [
          "In the distribution, go to Origins → Edit origin → Origin access control and copy the generated bucket policy",
          "Paste it into S3 → your bucket → Permissions → Bucket policy and save",
          "Back in CloudFront, set Default root object to index.html",
        ] },
        { t: "p", c: "After 5 to 10 minutes, your site loads at https://dxxxxxxxx.cloudfront.net over HTTPS. Try hitting the S3 URL directly and you get Access Denied, which is exactly what you want." },

        { t: "h", c: "Step 3: Attach AWS WAF" },
        { t: "p", c: "WAF inspects requests at the edge before they ever reach your origin." },
        { t: "ul", c: [
          "Open WAF & Shield → Web ACLs → Create web ACL",
          "Resource type: Global (CloudFront distributions are global resources regardless of your bucket's region)",
          "Name it, then under Associated AWS resources, add your CloudFront distribution",
          "Click Add rules → Add managed rule groups and select the Core rule set (covers SQLi and XSS patterns), and optionally the Amazon IP reputation list and Known bad inputs",
          "Default action: Allow requests that do not match rules. Never default to Block on a public site or you lock out legitimate users",
          "Create the Web ACL",
        ] },
        { t: "p", c: "Cost note: each managed rule group adds cost. The Core rule set alone is plenty for a learning project." },
        { t: "p", c: "Validate it works: append a script injection payload to your CloudFront URL, something like /?q=<script>alert(1)</script>. WAF should return a 403 Forbidden. Seeing that block confirms the Core rule set is actively inspecting traffic." },

        { t: "h", c: "Step 4: Least-Privilege IAM Access" },
        { t: "p", c: "Stop using the root account for day-to-day work." },
        { t: "ul", c: [
          "In IAM → Users → Add user, create a dedicated admin user with console access and a forced password reset on first sign-in",
          "Attach only the policies the project needs: S3, CloudFront, and WAF management, plus read-only IAM",
          "Create the user and store the sign-in URL and credentials securely",
          "Under Security credentials → Enable MFA, register an authenticator app",
        ] },
        { t: "p", c: "Improvement worth calling out: the managed FullAccess policies used here are a starting point. In a real environment I would scope these to the specific bucket and distribution ARNs. Broad managed policies are convenient for labs but they are not least privilege." },

        { t: "h", c: "Step 5: Monitoring and Compliance" },
        { t: "p", c: "Three services, three jobs. This is the mental model I use:" },
        { t: "ul", c: [
          "CloudWatch = operational monitoring. Metrics, alarms on request spikes or error rates, centralized logs",
          "CloudTrail = audit logging. Every API call recorded, answering \"who did what and when\"",
          "AWS Config = compliance checks. Continuously evaluates resource configuration against rules like \"all buckets must block public access\"",
        ] },
        { t: "p", c: "For a broader security posture, Security Hub aggregates findings, GuardDuty adds threat detection, and AWS Artifact supplies compliance reports (SOC, ISO, HIPAA) when auditors come knocking." },

        { t: "h", c: "Cleanup" },
        { t: "p", c: "To avoid surprise charges, tear down in this order:" },
        { t: "ul", c: [
          "Disable and delete the CloudFront distribution",
          "Empty and delete the S3 bucket",
          "Delete the WAF Web ACL",
          "Remove any CloudWatch alarms or log groups",
          "Delete the project-specific IAM user and policies",
        ] },

        { t: "h", c: "Key Takeaways" },
        { t: "ul", c: [
          "Private by default. The bucket never goes public; OAC makes CloudFront the sole reader",
          "Encrypt in transit. Redirecting HTTP to HTTPS at the viewer layer is a one-click win",
          "Filter at the edge. WAF blocks SQLi and XSS before requests reach your infrastructure",
          "Least privilege plus MFA. Dedicated IAM users, scoped permissions, no root account",
          "Log everything. CloudTrail and CloudWatch turn a static site into an auditable system",
        ] },
        { t: "p", c: "This pattern (S3 + CloudFront + OAC + WAF) is the foundation for nearly every secure static hosting setup on AWS, and it maps directly to controls you will see in SOC 2 and HIPAA environments: access restriction, encryption in transit, boundary protection, and audit logging." },
      ],
    },
    "build-a-vpc": {
      dek: "The VPC is the foundation everything else in AWS sits on. This walkthrough builds one from scratch twice — once in the console, once in CloudShell — and answers the \"why\" questions tutorials usually skip.",
      body: [
        { t: "p", c: "If you're starting out in cloud security or cloud engineering, the VPC is one of the first things you need to understand cold. It's the foundation everything else in AWS sits on top of: your EC2 instances, your databases, your load balancers. Get the VPC wrong, and everything built on it inherits the problem." },
        { t: "p", c: "This walkthrough builds a simple VPC from scratch, twice: once through the AWS console (so you can see what's happening), and once through CloudShell (so you can see how it's automated). Along the way, I'll answer the \"why\" questions that usually get skipped in tutorials." },

        { t: "h", c: "What is a VPC?" },
        { t: "p", c: "A VPC (Virtual Private Cloud) is your own private, isolated section of the AWS cloud. Think of it like renting an empty office floor in a shared building. AWS owns the building (their global data centers), but your floor is walled off. You decide who gets a key, how the rooms are laid out, and what's allowed in or out." },
        { t: "p", c: "Inside that \"floor,\" you control:" },
        { t: "ul", c: [
          "IP address ranges (who gets what address)",
          "Subnets (how the floor is divided into rooms)",
          "Routing (which hallways connect to which rooms, and to the outside)",
          "Security rules (who's allowed through which door)",
        ] },
        { t: "p", c: "Why would you want one? Because by default, nothing in AWS can talk to anything else, or to the internet, unless you explicitly allow it. A VPC gives you that control. It's the difference between leaving your office unlocked with no walls, and deciding exactly who can walk in, where they can go, and what they can access once they're there." },
        { t: "p", c: "For security engineers specifically, the VPC is where network segmentation, traffic control, and your \"deny by default\" posture actually get enforced." },

        { t: "h", c: "1. Create a VPC" },
        { t: "p", c: "Steps:" },
        { t: "ul", c: [
          "Type VPC in the AWS search bar and select VPC.",
          "In the left navigation menu, select Your VPCs.",
          "In the top right corner, select the AWS region closest to you. (You'll see a default VPC already listed here.)",
          "Choose Create VPC, then choose VPC Only.",
          "Name tag: My VPC — IPv4 CIDR: 10.0.0.0/16.",
          "Select Create VPC.",
        ] },
        { t: "p", c: "Why is there already a default VPC? AWS creates one default VPC per region automatically, so new accounts can launch resources (like an EC2 instance) immediately without configuring networking first. It comes pre-built with a subnet in each Availability Zone, an internet gateway already attached, and public IPs auto-assigned. It's convenient for quick testing, but in production you typically build custom VPCs (like the one above) so you control the design instead of inheriting AWS's defaults." },
        { t: "p", c: "What does that CIDR block mean? 10.0.0.0/16 defines your VPC's total address space, about 65,536 IP addresses. You'll carve smaller pieces out of this block for your subnets." },

        { t: "h", c: "What is a Subnet?" },
        { t: "p", c: "A subnet is a smaller, defined range of IP addresses within your VPC. Going back to the office analogy: if the VPC is the whole floor, a subnet is one room on that floor." },
        { t: "p", c: "Why would you need one? Because not everything on your floor should be treated the same way. Some rooms (subnets) should be reachable from outside, like a lobby. Others should stay locked down, like a server closet. Splitting your VPC into subnets is how you separate \"things the internet can reach\" (public subnets) from \"things that should never be directly exposed\" (private subnets), like databases." },

        { t: "h", c: "2. Create Subnets" },
        { t: "p", c: "Steps:" },
        { t: "ul", c: [
          "In the left navigation menu, select Subnets. (You'll see subnets already listed here too.)",
          "Choose Create subnet.",
          "VPC ID: select the VPC you just created.",
          "Subnet name: Public — Availability Zone: select the first one on the list.",
          "IPv4 VPC CIDR block: 10.0.0.0/16 — IPv4 subnet CIDR block: 10.0.0.0/24.",
          "Choose Create subnet.",
          "On the next screen, check the box next to Public.",
          "In the Actions menu (top right), select Edit subnet settings.",
          "Check the box for Enable auto-assign public IPv4 address, then click Save.",
        ] },
        { t: "p", c: "Why are subnets already listed there? Those are the subnets that came bundled with the default VPC, one per Availability Zone in that region. AWS pre-builds them for the same reason it pre-builds the default VPC: so you can launch something right away without setting up subnets manually." },
        { t: "p", c: "What does \"Enable auto-assign public IPv4 address\" actually do? It tells AWS to automatically give any instance launched in this subnet a public IP address. Without this setting, a new EC2 instance would only get a private IP, and nothing outside your VPC could reach it directly, even if everything else (routing, gateway) was set up correctly. This is what makes a subnet practically public, not just labeled \"Public.\"" },

        { t: "h", c: "What is an Internet Gateway?" },
        { t: "p", c: "An internet gateway is the door between your VPC and the public internet. Without it, your VPC is a sealed room. No traffic gets in, and nothing inside can reach the outside world, no matter how your subnets and routing are configured." },
        { t: "p", c: "Why would you need one? If you want any resource in your VPC (like a web server) to be reachable from the internet, or to reach out to the internet itself (like downloading updates), you need this gateway attached. It's the one piece that physically connects your private network to the outside." },

        { t: "h", c: "3. Create an Internet Gateway" },
        { t: "p", c: "Steps:" },
        { t: "ul", c: [
          "In the left navigation menu, select Internet Gateways. (You'll see one already listed, attached to the default VPC.)",
          "Choose Create internet gateway.",
          "Name tag: My VPC IG.",
          "Choose Create internet gateway.",
          "Select your newly created internet gateway, then choose Actions (top right corner).",
          "Select Attach to VPC, select My VPC, then select Attach internet gateway.",
        ] },
        { t: "p", c: "Why is there already an internet gateway? It's attached to the default VPC for the same reason that VPC has public subnets and auto-assign IPs turned on: AWS sets it up so resources are internet-reachable out of the box." },
        { t: "p", c: "What happens after attaching an internet gateway to a VPC? Attaching it just opens the door, it doesn't automatically route traffic through it. To actually use it, you need a route table entry that says \"send internet-bound traffic (0.0.0.0/0) to this gateway,\" and that route table needs to be associated with your public subnet. Without that routing step, the gateway sits attached but unused. (This routing step isn't in your original notes, but it's worth knowing as the next logical piece.)" },

        { t: "h", c: "4. Create a VPC with AWS CloudShell" },
        { t: "p", c: "Now let's do the same thing through the command line. This is useful because in real environments, networking gets built through code (Infrastructure as Code), not by clicking through a console every time. Open CloudShell from the AWS console, then:" },
        { t: "p", c: "Create the VPC — this returns your new VPC's ID. Save it, you'll need it in the next steps:" },
        { t: "code", c: "aws ec2 create-vpc --cidr-block 10.0.0.0/24 \\\n  --query Vpc.VpcId --output text" },
        { t: "p", c: "Tag the VPC with a name (replace VPC-ID with the ID returned above):" },
        { t: "code", c: "aws ec2 create-tags --resources VPC-ID \\\n  --tags Key=Name,Value=\"My VPC 2\"" },
        { t: "p", c: "Create a subnet inside that VPC. Replace VPC-ID with your VPC's ID, and ADD-CIDR-BLOCK-HERE with a smaller range inside your VPC's CIDR (for example, 10.0.0.0/25 if your VPC is 10.0.0.0/24):" },
        { t: "code", c: "aws ec2 create-subnet --vpc-id VPC-ID \\\n  --cidr-block ADD-CIDR-BLOCK-HERE" },
        { t: "p", c: "Go to your VPC in the console and select Resource Map to visually confirm what you just built. Then create an internet gateway and save the returned ID:" },
        { t: "code", c: "aws ec2 create-internet-gateway \\\n  --query InternetGateway.InternetGatewayId --output text" },
        { t: "p", c: "Attach the gateway to your VPC (replace VPC-ID and IG-ID with the values you saved):" },
        { t: "code", c: "aws ec2 attach-internet-gateway --vpc-id VPC-ID \\\n  --internet-gateway-id IG-ID" },

        { t: "h", c: "The takeaway" },
        { t: "p", c: "Every piece here builds on the last one:" },
        { t: "ul", c: [
          "VPC = your isolated network space.",
          "Subnet = a smaller zone inside that space, public or private.",
          "Internet Gateway = the door connecting your network to the internet.",
          "Route table (the missing piece worth remembering) = what actually tells traffic to use that door.",
        ] },
        { t: "quote", c: "An internet gateway just opens the door. A route table is what tells traffic to walk through it." },
        { t: "p", c: "Once you're comfortable building this manually, in both the console and the CLI, the natural next step is automating it with Infrastructure as Code (Terraform or CloudFormation) so your network design is repeatable and version-controlled instead of click-built every time." },
      ],
    },
  };

  window.V3_ARTICLES = ARTICLES;
})();
